"""Generate and check the local AI model pins the product's component engine trusts.

``just pin-local-ai`` regenerates, beside the program table, the derived facts
of ``src/cadrumo/_data/dependencies/local_ai_models.toml``. For every pinned
model it fetches the model registry's manifest for the tag over HTTPS from the
declared model-registry hosts, and records the SHA-256 of the manifest bytes
(the identity the local AI program reports for the installed weights) and the
sum of the manifest's layer and configuration sizes. The roles, memory floors
and licences are reviewed facts: the generator keeps them as committed. Review
the diff: a changed digest means the publisher retagged the weights.

``--check`` downloads nothing. It validates the committed table, its hosts
against the declared group, and that it is exactly what the renderer writes.
"""

from __future__ import annotations

import hashlib
import json
from collections.abc import Callable
from dataclasses import dataclass
from typing import Final, Literal
from urllib.parse import urlsplit

import httpx
from pydantic import BaseModel, ConfigDict, Field, PositiveInt

from cadrumo.core.external_constants import load_external_constants
from cadrumo.core.local_ai_pins import LocalAiModelPin, LocalAiModelPins, parse_local_ai_model_pins
from dev._paths import REPO_ROOT

MODELS_PATH: Final = REPO_ROOT / "src" / "cadrumo" / "_data" / "dependencies" / "local_ai_models.toml"

#: The declared host group the model manifests and weights are fetched from.
HOST_GROUP: Final = "model_registry"

_REGISTRY: Final = "https://registry.ollama.ai/v2/library"
_MANIFEST_MEDIA_TYPE: Final = "application/vnd.docker.distribution.manifest.v2+json"
_MANIFEST_BYTES_LIMIT: Final = 1024 * 1024
_TIMEOUT_S: Final = 60.0

#: Fetches one address; returns the body and every host the request passed through.
type Fetch = Callable[[str], tuple[bytes, frozenset[str]]]

_BLOB_CONFIG: Final = ConfigDict(strict=True, frozen=True, extra="ignore")


class _Blob(BaseModel):
    """One content-addressed part a manifest names: the configuration or a layer."""

    model_config = _BLOB_CONFIG

    digest: str = Field(pattern=r"^sha256:[0-9a-f]{64}$")
    size: PositiveInt


class _Manifest(BaseModel):
    """The parts of a registry image manifest the pins are derived from."""

    model_config = _BLOB_CONFIG

    schema_version: Literal[2] = Field(alias="schemaVersion")
    config: _Blob
    layers: tuple[_Blob, ...] = Field(min_length=1)


@dataclass(frozen=True, slots=True)
class ManifestFacts:
    """What one manifest pins: its own digest and the bytes a pull downloads."""

    manifest_digest: str
    download_bytes: int


def manifest_url(name: str) -> str:
    """Return the registry address of the manifest for the model tag ``name``."""
    model, tag = name.split(":", 1)
    return f"{_REGISTRY}/{model}/manifests/{tag}"


def manifest_facts(manifest: bytes) -> ManifestFacts:
    """Derive the pinned facts from the exact manifest bytes the registry served.

    Raises:
        ValueError: When the bytes are not a bounded version 2 image manifest.
    """
    if len(manifest) > _MANIFEST_BYTES_LIMIT:
        raise ValueError("a manifest is larger than any registry serves")
    parsed = _Manifest.model_validate_json(manifest)
    return ManifestFacts(
        manifest_digest=hashlib.sha256(manifest).hexdigest(),
        download_bytes=parsed.config.size + sum(layer.size for layer in parsed.layers),
    )


def generate_model_pins(committed: LocalAiModelPins, fetch: Fetch) -> LocalAiModelPins:
    """Re-derive every pinned model's digest and size, keeping the reviewed facts as committed."""
    hosts: set[str] = set()
    models: list[LocalAiModelPin] = []
    for pin in committed.models:
        body, visited = fetch(manifest_url(pin.name))
        facts = manifest_facts(body)
        hosts |= visited
        models.append(
            LocalAiModelPin.model_validate(
                pin.model_dump() | {"manifest_digest": facts.manifest_digest, "download_bytes": facts.download_bytes}
            )
        )
    return LocalAiModelPins.model_validate(
        {
            "hosts": sorted(hosts),
            "roles": dict(committed.roles),
            "models": models,
        }
    )


def render_model_pins(pins: LocalAiModelPins) -> str:
    """Render the table as the TOML the engine and the catalogue read, in the table's order."""
    lines = [
        "# Generated by `just pin-local-ai`, which reads `manifest_digest` and `download_bytes`",
        "# from the model registry's manifest for each tag and keeps the reviewed roles,",
        "# `memory_bytes`, `licence` and `commercial_use_permitted` as committed.",
        "#",
        "# `manifest_digest` is the SHA-256 of the manifest bytes, the identity the local AI",
        "# program reports for the installed weights, and `download_bytes` is the sum of the",
        "# manifest's layer and configuration sizes. `memory_bytes` is the publisher's stated",
        "# weight size for the pulled quantisation: the requirement before any safety margin,",
        "# and the hardware floor a computer must clear. `licence` is the SPDX identifier the",
        "# catalogue verified against the publisher's own text.",
        "",
        "hosts = [",
        *(f"  {json.dumps(host)}," for host in pins.hosts),
        "]",
        "",
        "[roles]",
        *(f"{role} = {json.dumps(model)}" for role, model in pins.roles.items()),
    ]
    for pin in pins.models:
        lines += [
            "",
            "[[models]]",
            f"name = {json.dumps(pin.name)}",
            f"manifest_digest = {json.dumps(pin.manifest_digest)}",
            f"download_bytes = {pin.download_bytes}",
            f"memory_bytes = {pin.memory_bytes}",
            f"licence = {json.dumps(pin.licence)}",
            f"commercial_use_permitted = {json.dumps(pin.commercial_use_permitted)}",
        ]
    return "\n".join(lines) + "\n"


def load_model_pins(text: str | None = None) -> LocalAiModelPins:
    """Validate the committed table, or the one ``text`` holds."""
    return parse_local_ai_model_pins(MODELS_PATH.read_text(encoding="utf-8") if text is None else text)


def declared_hosts() -> frozenset[str]:
    """Return the hosts the model downloads are declared to pass through."""
    return frozenset(load_external_constants().dependency_hosts.hosts_for(HOST_GROUP))


def check_model_pins(pins: LocalAiModelPins, rendered: str) -> list[str]:
    """Return every way the committed table differs from the declarations and the renderer."""
    problems: list[str] = []
    undeclared = sorted(set(pins.hosts) - declared_hosts())
    if undeclared:
        problems.append(f"the model table names undeclared hosts {undeclared}")
    if list(pins.hosts) != sorted(set(pins.hosts)):
        problems.append("the model table lists its hosts out of order")
    for pin in pins.models:
        if (urlsplit(manifest_url(pin.name)).hostname or "") not in pins.hosts:
            problems.append(f"{pin.name} is served from a host the model table does not name")
    if render_model_pins(pins) != rendered:
        problems.append("the model table is not what the generator renders")
    return problems


def registry_fetch(hosts: frozenset[str]) -> tuple[Fetch, Callable[[], None]]:
    """Return a fetch that refuses any hop outside ``hosts`` or over plain HTTP, and its closer."""
    client = httpx.Client(follow_redirects=True, trust_env=False, timeout=_TIMEOUT_S)

    def fetch(url: str) -> tuple[bytes, frozenset[str]]:
        with client.stream("GET", url, headers={"Accept": _MANIFEST_MEDIA_TYPE}) as response:
            visited: set[str] = set()
            for hop in (*response.history, response):
                if hop.url.scheme != "https" or hop.url.host not in hosts:
                    raise RuntimeError(f"a manifest request left the declared hosts at {hop.url.host}")
                visited.add(hop.url.host)
            response.raise_for_status()
            body = bytearray()
            for chunk in response.iter_bytes():
                body += chunk
                if len(body) > _MANIFEST_BYTES_LIMIT:
                    raise RuntimeError(f"the manifest at {url} is larger than any registry serves")
        return bytes(body), frozenset(visited)

    return fetch, client.close
